import { User, UserRole } from '../types';
import { MOCK_USERS } from '../constants';

// CONSTANTS FOR SECURITY
const EMAIL_DOMAIN = 'internal.schoolapp.com';

/**
 * THE SYNTHETIC EMAIL LOGIC
 * This function simulates the backend wrapper around Firebase Auth.
 * In a real implementation, this would happen on the server/cloud function
 * or be pre-calculated before sending to client SDK.
 */
export const generateSyntheticEmail = (schoolID: string): string => {
  // Sanitize ID to ensure it's email safe
  const sanitizedID = schoolID.trim().toUpperCase().replace(/[^A-Z0-9-]/g, '');
  return `${sanitizedID}@${EMAIL_DOMAIN}`;
};

export const loginWithSchoolID = async (schoolID: string, password: string): Promise<User> => {
  return new Promise((resolve, reject) => {
    // Simulate network delay
    setTimeout(() => {
      // 1. Generate the synthetic email (The invisible step)
      const syntheticEmail = generateSyntheticEmail(schoolID);

      console.log(`[AUTH DEBUG] Converting ID "${schoolID}" to Synthetic Email: "${syntheticEmail}"`);

      // 2. Mock Firebase Auth Check
      // In a real app, we would call: await signInWithEmailAndPassword(auth, syntheticEmail, password);

      const user = MOCK_USERS.find(u => u.schoolID === schoolID);

      if (user) {
        // Mock password check (allow any password for demo if ID exists)
        if (password.length > 0) {
           resolve({
             ...user,
             email: syntheticEmail // Attach the generated email to the session
           });
        } else {
          reject(new Error("Password is required."));
        }
      } else {
        reject(new Error("Invalid School ID or Password."));
      }
    }, 800);
  });
};

export const logout = async (): Promise<void> => {
  return new Promise((resolve) => setTimeout(resolve, 500));
};

import React from 'react';
import { User, UserRole } from '../types';
import { 
  LayoutDashboard, 
  Users, 
  BookOpen, 
  Settings, 
  LogOut, 
  GraduationCap,
  ShieldAlert
} from 'lucide-react';

interface SidebarProps {
  user: User;
  onLogout: () => void;
  currentPage: string;
  onNavigate: (page: string) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ user, onLogout, currentPage, onNavigate }) => {

  const getMenuItems = () => {
    const common = [
      { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
      { id: 'profile', label: 'My Profile', icon: Users },
    ];

    if (user.role === UserRole.PRINCIPAL) {
      return [
        ...common,
        { id: 'academics', label: 'Academics', icon: BookOpen },
        { id: 'settings', label: 'School Settings', icon: Settings },
      ];
    }

    if (user.role === UserRole.TEACHER) {
      return [
        ...common,
        { id: 'classes', label: 'My Classes', icon: BookOpen },
      ];
    }

    if (user.role === UserRole.STUDENT) {
      return [
        ...common,
        { id: 'grades', label: 'My Grades', icon: GraduationCap },
      ];
    }

    if (user.role === UserRole.SUPREME_ADMIN) {
      return [
        { id: 'dashboard', label: 'System Overview', icon: ShieldAlert },
        { id: 'db-management', label: 'DB Management', icon: Settings },
      ];
    }

    return common;
  };

  const menuItems = getMenuItems();

  return (
    <div className="h-screen w-64 bg-slate-900 text-white flex flex-col fixed left-0 top-0 shadow-xl z-50 transition-all">
      <div className="p-6 border-b border-slate-700">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center font-bold text-xl">
            N
          </div>
          <div>
            <h1 className="font-bold text-lg tracking-tight">NEXUS ERP</h1>
            <p className="text-xs text-slate-400">School Management</p>
          </div>
        </div>
      </div>

      <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
        {menuItems.map((item) => {
          const Icon = item.icon;
          const active = currentPage === item.id;
          return (
            <button
              key={item.id}
              onClick={() => onNavigate(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${
                active 
                  ? 'bg-blue-600 text-white shadow-md' 
                  : 'text-slate-400 hover:bg-slate-800 hover:text-white'
              }`}
            >
              <Icon size={20} />
              <span className="font-medium text-sm">{item.label}</span>
