import React, { useState } from 'react';
import { loginWithSchoolID } from '../services/authService';
import { User } from '../types';
import { Loader2, School } from 'lucide-react';

interface LoginProps {
  onLoginSuccess: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLoginSuccess }) => {
  const [schoolID, setSchoolID] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      const user = await loginWithSchoolID(schoolID, password);
      onLoginSuccess(user);
    } catch (err: any) {
      setError(err.message || 'Login failed');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 px-4">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-xl overflow-hidden">
        {/* Header */}
        <div className="bg-blue-600 p-8 text-center">
          <div className="w-16 h-16 bg-white/20 rounded-full flex items-center justify-center mx-auto mb-4 backdrop-blur-sm">
            <School className="text-white w-8 h-8" />
          </div>
          <h2 className="text-3xl font-bold text-white mb-2">Nexus ERP</h2>
          <p className="text-blue-100">Secure School Management Portal</p>
        </div>

        {/* Form */}
        <div className="p-8">
          <form onSubmit={handleSubmit} className="space-y-6">
            {error && (
              <div className="p-3 bg-red-50 text-red-600 text-sm rounded-lg border border-red-100 flex items-center">
                {error}
              </div>
            )}

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">
                School ID
              </label>
              <input
                type="text"
                value={schoolID}
                onChange={(e) => setSchoolID(e.target.value)}
                className="w-full px-4 py-3 rounded-lg border border-slate-200 focus:border-blue-500 focus:ring-2 focus:ring-blue-200 outline-none transition-all text-slate-900 font-mono placeholder:font-sans"
                placeholder="e.g., TCH-550"
                required
              />
              <p className="mt-1 text-xs text-slate-400">
                Enter your assigned ID (e.g., STD-2024-001)
              </p>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">
                Password
              </label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-3 rounded-lg border border-slate-200 focus:border-blue-500 focus:ring-2 focus:ring-blue-200 outline-none transition-all text-slate-900"
                placeholder="••••••••"
                required
              />
            </div>

            <button
              type="submit"
              disabled={isLoading}
              className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 rounded-lg transition-colors flex items-center justify-center"
            >
              {isLoading ? (
                <>
                  <Loader2 className="animate-spin mr-2 h-5 w-5" />
                  Authenticating...
                </>
              ) : (
                'Access Portal'
              )}
            </button>
          </form>

          <div className="mt-8 text-center">
            <p className="text-xs text-slate-400">
              Technical Support: helpdesk@internal.schoolapp.com
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState } from 'react';
import { MOCK_CLASS_ROSTER } from '../constants';
import { StudentRecord } from '../types';
import { CheckSquare, Square, Save, Search, Filter } from 'lucide-react';

const TeacherDashboard: React.FC = () => {
  const [students, setStudents] = useState<StudentRecord[]>(MOCK_CLASS_ROSTER);
  const [hasChanges, setHasChanges] = useState(false);

  const handleToggleAttendance = (id: string) => {
    setStudents(prev => prev.map(s => {
      if (s.id === id) {
        return { ...s, attendanceToday: s.attendanceToday === false ? true : false }; 
        // Logic: Toggle between Present (true) and Absent (false). Default null treats as Present for initial toggle.
      }
      return s;
    }));
    setHasChanges(true);
  };

  const markAllPresent = () => {
    setStudents(prev => prev.map(s => ({ ...s, attendanceToday: true })));
    setHasChanges(true);
  };

  const saveAttendance = () => {
    // In real app, API call here
    alert("Attendance saved to Firestore!");
    setHasChanges(false);
  };

  const getAttendanceStatusColor = (status: boolean | null) => {
    if (status === true) return 'bg-green-100 text-green-700 border-green-200';
    if (status === false) return 'bg-red-100 text-red-700 border-red-200';
    return 'bg-slate-100 text-slate-500 border-slate-200';
  };

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Class 10-A</h1>
          <p className="text-slate-500">Daily Attendance & Roster</p>
        </div>

        <div className="flex items-center gap-3">
           <button 
            onClick={markAllPresent}
            className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 text-slate-700 font-medium rounded-lg hover:bg-slate-50 transition-colors shadow-sm"
          >
            <CheckSquare size={18} />
            Mark All Present
          </button>

          <button 
            onClick={saveAttendance}
            disabled={!hasChanges}
            className={`flex items-center gap-2 px-6 py-2 font-medium rounded-lg transition-all shadow-sm ${
              hasChanges 
              ? 'bg-blue-600 text-white hover:bg-blue-700' 
              : 'bg-slate-200 text-slate-400 cursor-not-allowed'
            }`}
          >
            <Save size={18} />
            Save Records
          </button>
        </div>
      </header>

      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        {/* Table Controls */}
        <div className="p-4 border-b border-slate-100 flex items-center justify-between">
            <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 h-4 w-4" />
                <input 
                    type="text" 
                    placeholder="Search student..." 
                    className="pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-100"
                />
            </div>
            <button className="p-2 text-slate-500 hover:bg-slate-50 rounded-lg">
                <Filter size={18} />
            </button>
        </div>

        {/* List */}
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-slate-500 text-xs uppercase font-semibold">
              <tr>
                <th className="px-6 py-4">Roll #</th>
                <th className="px-6 py-4">Student Name</th>
                <th className="px-6 py-4">School ID</th>
                <th className="px-6 py-4 text-center">Status</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {students.map((student) => {
                const isPresent = student.attendanceToday === true;
                const isAbsent = student.attendanceToday === false;

                return (
                  <tr key={student.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 py-4 text-slate-500">#{student.rollNumber}</td>
                    <td className="px-6 py-4">
                      <div className="font-medium text-slate-900">{student.name}</div>
                      <div className="text-xs text-slate-400">Grade Avg: {student.gradeAverage}%</div>
                    </td>
                    <td className="px-6 py-4 font-mono text-sm text-slate-500">
                      {student.schoolID}
                    </td>
                    <td className="px-6 py-4 text-center">
                        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border ${getAttendanceStatusColor(student.attendanceToday)}`}>
                            {isPresent ? 'Present' : isAbsent ? 'Absent' : 'Not Marked'}
                        </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex items-center justify-end gap-2">
                        <button 
                            onClick={() => handleToggleAttendance(student.id)}
                            className={`p-2 rounded-lg transition-colors ${
                                isPresent 
                                ? 'bg-green-100 text-green-700 hover:bg-green-200' 
                                : 'bg-slate-100 text-slate-400 hover:bg-slate-200'
                            }`}
                            title="Mark Present"
                        >
                            <CheckSquare size={18} />
                        </button>
                        <button 
                            onClick={() => handleToggleAttendance(student.id)}
                            className={`p-2 rounded-lg transition-colors ${
                                isAbsent 
                                ? 'bg-red-100 text-red-700 hover:bg-red-200' 
                                : 'bg-slate-100 text-slate-400 hover:bg-slate-200'
                            }`}
                            title="Mark Absent"
                        >
                            <Square size={18} className={isAbsent ? "fill-current" : ""} />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

