import React, { useState, useEffect } from 'react';
import Login from './pages/Login';
import PrincipalDashboard from './pages/PrincipalDashboard';
import TeacherDashboard from './pages/TeacherDashboard';
import StudentDashboard from './pages/StudentDashboard';
import AdminDashboard from './pages/AdminDashboard';
import Sidebar from './components/Sidebar';
import { User, UserRole } from './types';
import { logout } from './services/authService';

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [currentPage, setCurrentPage] = useState('dashboard');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check local storage for persistent session (Simulated)
    const storedUser = localStorage.getItem('nexus_user');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
    setLoading(false);
  }, []);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    localStorage.setItem('nexus_user', JSON.stringify(loggedInUser));
    setCurrentPage('dashboard');
  };

  const handleLogout = async () => {
    await logout();
    setUser(null);
    localStorage.removeItem('nexus_user');
  };

  const renderDashboard = () => {
    if (!user) return null;

    if (user.role === UserRole.SUPREME_ADMIN) {
        return <AdminDashboard />;
    }

    if (currentPage === 'dashboard') {
      switch (user.role) {
        case UserRole.PRINCIPAL:
          return <PrincipalDashboard />;
        case UserRole.TEACHER:
          return <TeacherDashboard />;
        case UserRole.STUDENT:
          return <StudentDashboard user={user} />;
        default:
          return <div className="p-8">Role not supported yet.</div>;
      }
    }

    // Fallback pages (Mocked for navigation demo)
    return (
      <div className="flex flex-col items-center justify-center h-full text-slate-400">
        <h2 className="text-2xl font-bold mb-2">Work in Progress</h2>
        <p>The "{currentPage}" module is currently under development.</p>
      </div>
    );
  };

  if (loading) {
    return <div className="min-h-screen flex items-center justify-center bg-slate-100">Loading...</div>;
  }

  if (!user) {
    return <Login onLoginSuccess={handleLogin} />;
  }

  // Ghost Admin Layout Override
  if (user.role === UserRole.SUPREME_ADMIN) {
      return (
          <div className="bg-black min-h-screen">
             <div className="container mx-auto pt-10">
                 <button onClick={handleLogout} className="text-red-500 text-xs mb-4 hover:underline px-8">ABORT SESSION</button>
                 {renderDashboard()}
             </div>
          </div>
      )
  }

  // Standard App Layout
  return (
    <div className="flex min-h-screen bg-slate-50">
      <Sidebar 
        user={user} 
        onLogout={handleLogout} 
        currentPage={currentPage}
        onNavigate={setCurrentPage}
      />
      <main className="flex-1 ml-64 p-8 transition-all">
        <div className="max-w-7xl mx-auto">
          {renderDashboard()}
        </div>
      </main>
    </div>
  );
}

export default App;

import { User, UserRole, StudentRecord } from '../types';

const STORAGE_KEY_USERS = 'nexus_erp_users';
const STORAGE_KEY_STUDENTS = 'nexus_erp_students';

// Initial Seed: ONLY the Supreme Admin
const INITIAL_USERS: User[] = [
  {
    uid: 'u_admin',
    schoolID: 'GHOST-ADMIN',
    name: 'System Administrator',
    role: UserRole.SUPREME_ADMIN,
    avatarUrl: 'https://ui-avatars.com/api/?name=System+Admin&background=10b981&color=fff'
  }
];

export const getStoredUsers = (): User[] => {
  const stored = localStorage.getItem(STORAGE_KEY_USERS);
  if (!stored) {
    localStorage.setItem(STORAGE_KEY_USERS, JSON.stringify(INITIAL_USERS));
    return INITIAL_USERS;
  }
  return JSON.parse(stored);
};

export const addUser = (user: User): void => {
  const users = getStoredUsers();
  users.push(user);
  localStorage.setItem(STORAGE_KEY_USERS, JSON.stringify(users));
};

export const getStoredStudents = (): StudentRecord[] => {
  const stored = localStorage.getItem(STORAGE_KEY_STUDENTS);
  return stored ? JSON.parse(stored) : [];
};

export const addStudent = (student: StudentRecord): void => {
  const students = getStoredStudents();
  students.push(student);
  localStorage.setItem(STORAGE_KEY_STUDENTS, JSON.stringify(students));
};

export const updateStudent = (updatedStudent: StudentRecord): void => {
  const students = getStoredStudents();
  const index = students.findIndex(s => s.id === updatedStudent.id);
  if (index !== -1) {
    students[index] = updatedStudent;
    localStorage.setItem(STORAGE_KEY_STUDENTS, JSON.stringify(students));
  }
};

// Helper to generate IDs
export const generateId = (prefix: string): string => {
  return `${prefix}-${Math.floor(Math.random() * 10000)}`;
};

import { User } from '../types';
import { getStoredUsers, generateId } from './storage';

// CONSTANTS FOR SECURITY
const EMAIL_DOMAIN = 'internal.schoolapp.com';

export const generateSyntheticEmail = (schoolID: string): string => {
  const sanitizedID = schoolID.trim().toUpperCase().replace(/[^A-Z0-9-]/g, '');
  return `${sanitizedID}@${EMAIL_DOMAIN}`;
};

export const loginWithSchoolID = async (schoolID: string, password: string): Promise<User> => {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      const syntheticEmail = generateSyntheticEmail(schoolID);
      console.log(`[AUTH DEBUG] Converting ID "${schoolID}" to Synthetic Email: "${syntheticEmail}"`);

      const users = getStoredUsers();
      const user = users.find(u => u.schoolID === schoolID);

      if (user) {
        // In a real app, verify password hash. For demo, accept any non-empty password.
        if (password.length > 0) {
           resolve({
             ...user,
             email: syntheticEmail 
           });
        } else {
          reject(new Error("Password is required."));
        }
      } else {
        reject(new Error("Invalid School ID."));
      }
    }, 800);
  });
};

export const logout = async (): Promise<void> => {
  return new Promise((resolve) => setTimeout(resolve, 500));
};

