// CONSTANTS FOR SECURITY
const EMAIL_DOMAIN = 'internal.schoolapp.com';

export const generateSyntheticEmail = (schoolID: string): string => {
  const sanitizedID = schoolID.trim().toUpperCase().replace(/[^A-Z0-9-]/g, '');
  return `${sanitizedID}@${EMAIL_DOMAIN}`;
};

export const loginWithSchoolID = async (schoolID: string, password: string): Promise<User> => {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      const syntheticEmail = generateSyntheticEmail(schoolID);
      console.log(`[AUTH DEBUG] Converting ID "${schoolID}" to Synthetic Email: "${syntheticEmail}"`);

      const users = getStoredUsers();
      const user = users.find(u => u.schoolID === schoolID);

      if (user) {
        // Enforce specific password if set (e.g. for Admin)
        if (user.password && user.password !== password) {
          reject(new Error("Invalid Password."));
          return;
        }

        // Standard check for other users (allow any non-empty password if not strictly set)
        if (password.length > 0) {
           resolve({
             ...user,
             email: syntheticEmail 
           });
        } else {
          reject(new Error("Password is required."));
        }
      } else {
        reject(new Error("Invalid School ID."));
      }
    }, 800);
  });
};

export const logout = async (): Promise<void> => {
  return new Promise((resolve) => setTimeout(resolve, 500));
};

