  const teachers = users.filter(u => u.role === UserRole.TEACHER);
  const students = users.filter(u => u.role === UserRole.STUDENT); // Usually students are added by teachers, but Principal can see count

  // --- SUB-PAGES RENDERING ---

  if (currentPage === 'settings') {
