      {/* Top Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-4">
            <div className="p-3 bg-blue-100 rounded-lg">
              <Users className="text-blue-600 h-6 w-6" />
            </div>
            <span className="text-xs font-semibold px-2 py-1 bg-green-100 text-green-700 rounded-full">
              Live
            </span>
          </div>
          <h3 className="text-slate-500 text-sm font-medium">Total Staff</h3>
          <p className="text-2xl font-bold text-slate-800">{teachers.length}</p>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-4">
            <div className="p-3 bg-green-100 rounded-lg">
              <UserCheck className="text-green-600 h-6 w-6" />
            </div>
          </div>
          <h3 className="text-slate-500 text-sm font-medium">Students Enrolled</h3>
          <p className="text-2xl font-bold text-slate-800">{students.length || 'N/A'}</p>
        </div>

        {/* Mock stats for visuals */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-4">
            <div className="p-3 bg-red-100 rounded-lg">
              <AlertTriangle className="text-red-600 h-6 w-6" />
            </div>
          </div>
          <h3 className="text-slate-500 text-sm font-medium">Absent Staff</h3>
          <p className="text-2xl font-bold text-slate-800">0</p>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-4">
            <div className="p-3 bg-purple-100 rounded-lg">
              <TrendingUp className="text-purple-600 h-6 w-6" />
            </div>
          </div>
          <h3 className="text-slate-500 text-sm font-medium">Avg Performance</h3>
          <p className="text-2xl font-bold text-slate-800">B+</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Attendance Chart */}
        <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-6">
            <h3 className="font-bold text-slate-800">Weekly Attendance Trends</h3>
          </div>
          <div className="h-72 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={WEEKLY_ATTENDANCE}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{ fill: '#64748b', fontSize: 12 }} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{ fill: '#64748b', fontSize: 12 }} />
                <Tooltip cursor={{ fill: '#f8fafc' }} contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} />
                <Bar dataKey="present" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={40} />
                <Bar dataKey="absent" fill="#ef4444" radius={[4, 4, 0, 0]} barSize={40} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Calendar / Events */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="font-bold text-slate-800 mb-4">Upcoming Events</h3>
          <div className="space-y-4">
            {[
              { title: "Staff Meeting", time: "10:00 AM", type: "Academic" },
              { title: "Parent-Teacher Conf", time: "2:00 PM", type: "General" },
            ].map((event, idx) => (
              <div key={idx} className="flex items-start gap-3 pb-3 border-b border-slate-50 last:border-0 last:pb-0">
                <div className="p-2 bg-slate-50 rounded-lg">
                  <Calendar className="text-slate-400 h-5 w-5" />
                </div>
                <div>
                  <h4 className="text-sm font-semibold text-slate-700">{event.title}</h4>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-xs text-slate-500">{event.time}</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default PrincipalDashboard;

import { User, UserRole, StudentRecord } from '../types';

// Bumped version to v2 to ensure old "GHOST-ADMIN" data is cleared and new credentials take effect
const STORAGE_KEY_USERS = 'nexus_erp_users_v2';
const STORAGE_KEY_STUDENTS = 'nexus_erp_students_v2';

// Initial Seed: ONLY the Supreme Admin with requested credentials
const INITIAL_USERS: User[] = [
  {
    uid: 'u_admin',
    schoolID: 'admin9945',
    name: 'System Administrator',
    role: UserRole.SUPREME_ADMIN,
    avatarUrl: 'https://ui-avatars.com/api/?name=System+Admin&background=10b981&color=fff',
    password: '201212'
  }
];

export const getStoredUsers = (): User[] => {
  const stored = localStorage.getItem(STORAGE_KEY_USERS);
  if (!stored) {
    localStorage.setItem(STORAGE_KEY_USERS, JSON.stringify(INITIAL_USERS));
    return INITIAL_USERS;
  }
  return JSON.parse(stored);
};

export const addUser = (user: User): void => {
  const users = getStoredUsers();
  users.push(user);
  localStorage.setItem(STORAGE_KEY_USERS, JSON.stringify(users));
};

export const updateUser = (updatedUser: User): void => {
  const users = getStoredUsers();
  const index = users.findIndex(u => u.uid === updatedUser.uid);
  if (index !== -1) {
    users[index] = updatedUser;
    localStorage.setItem(STORAGE_KEY_USERS, JSON.stringify(users));
  }
};

export const removeUser = (uid: string): void => {
  let users = getStoredUsers();
  users = users.filter(u => u.uid !== uid);
  localStorage.setItem(STORAGE_KEY_USERS, JSON.stringify(users));
};

export const getStoredStudents = (): StudentRecord[] => {
  const stored = localStorage.getItem(STORAGE_KEY_STUDENTS);
  return stored ? JSON.parse(stored) : [];
};

export const addStudent = (student: StudentRecord): void => {
  const students = getStoredStudents();
  students.push(student);
  localStorage.setItem(STORAGE_KEY_STUDENTS, JSON.stringify(students));
};

export const updateStudent = (updatedStudent: StudentRecord): void => {
  const students = getStoredStudents();
  const index = students.findIndex(s => s.id === updatedStudent.id);
  if (index !== -1) {
    students[index] = updatedStudent;
    localStorage.setItem(STORAGE_KEY_STUDENTS, JSON.stringify(students));
  }
};

// Helper to generate IDs
export const generateId = (prefix: string): string => {
  return `${prefix}-${Math.floor(Math.random() * 10000)}`;
};

import React, { useState, useEffect } from 'react';
import { User, UserRole } from '../types';
import { getStoredUsers, addUser, updateUser, removeUser, generateId } from '../services/storage';
import { Shield, Plus, UserPlus, School, Search, Trash2, Pencil } from 'lucide-react';

const AdminDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'overview' | 'principals'>('overview');
  const [users, setUsers] = useState<User[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);

  // Form State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [newPrincipalName, setNewPrincipalName] = useState('');
  const [newPrincipalID, setNewPrincipalID] = useState('');
  const [newPrincipalPassword, setNewPrincipalPassword] = useState('');

  useEffect(() => {
    setUsers(getStoredUsers());
  }, []);

  const openAddModal = () => {
    setEditingId(null);
    setNewPrincipalName('');
    setNewPrincipalID('');
    setNewPrincipalPassword('');
    setShowAddModal(true);
  };

  const openEditModal = (user: User) => {
    setEditingId(user.uid);
    setNewPrincipalName(user.name);
    setNewPrincipalID(user.schoolID);
    setNewPrincipalPassword(user.password || '');
    setShowAddModal(true);
  };

  const handleSavePrincipal = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId) {
      // Update existing
      const updatedUser: User = {
        ...users.find(u => u.uid === editingId)!,
        name: newPrincipalName,
        schoolID: newPrincipalID,
        password: newPrincipalPassword,
        avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(newPrincipalName)}&background=3b82f6&color=fff`
      };
      updateUser(updatedUser);
      alert(`Principal ${updatedUser.name} updated!`);
    } else {
      // Create new
      const newUser: User = {
        uid: generateId('u'),
        name: newPrincipalName,
        schoolID: newPrincipalID,
        role: UserRole.PRINCIPAL,
        avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(newPrincipalName)}&background=3b82f6&color=fff`,
        password: newPrincipalPassword
      };
      addUser(newUser);
      alert(`Principal ${newUser.name} added!`);
    }

    setUsers(getStoredUsers()); // Refresh list
    setShowAddModal(false);

    // Reset form
    setNewPrincipalName('');
    setNewPrincipalID('');
    setNewPrincipalPassword('');
    setEditingId(null);
  };

  const handleRemovePrincipal = (uid: string, name: string) => {
    if (window.confirm(`Are you sure you want to remove Principal "${name}"? This action cannot be undone.`)) {
      removeUser(uid);
      setUsers(getStoredUsers()); // Refresh list
    }
  };

  const principals = users.filter(u => u.role === UserRole.PRINCIPAL);

  return (
    <div className="space-y-6">
      <header className="flex justify-between items-center mb-8">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">System Administration</h1>
          <p className="text-slate-500">Manage school instances and principals</p>
        </div>
        <div className="flex gap-2">
            <button 
                onClick={() => setActiveTab('overview')}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'overview' ? 'bg-slate-800 text-white' : 'bg-white text-slate-600 hover:bg-slate-50'}`}
            >
                Overview
            </button>
            <button 
                onClick={() => setActiveTab('principals')}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === 'principals' ? 'bg-slate-800 text-white' : 'bg-white text-slate-600 hover:bg-slate-50'}`}
            >
                Manage Principals
            </button>
        </div>
      </header>

      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
            <div className="p-3 bg-blue-100 w-fit rounded-lg mb-4">
              <School className="text-blue-600 h-6 w-6" />
            </div>
            <h3 className="text-slate-500 text-sm font-medium">Active Principals</h3>
            <p className="text-3xl font-bold text-slate-800">{principals.length}</p>
          </div>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
            <div className="p-3 bg-green-100 w-fit rounded-lg mb-4">
              <Shield className="text-green-600 h-6 w-6" />
            </div>
            <h3 className="text-slate-500 text-sm font-medium">System Status</h3>
            <p className="text-3xl font-bold text-green-600">Healthy</p>
          </div>
        </div>
      )}

      {activeTab === 'principals' && (
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          <div className="p-6 border-b border-slate-100 flex justify-between items-center">
            <h2 className="text-lg font-bold text-slate-800">Principal Accounts</h2>
            <button 
              onClick={openAddModal}
              className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
            >
              <Plus size={18} />
              Add Principal
            </button>
          </div>

          <table className="w-full text-left">
            <thead className="bg-slate-50 text-slate-500 text-xs uppercase">
              <tr>
                <th className="px-6 py-4">Name</th>
                <th className="px-6 py-4">School ID (Login)</th>
                <th className="px-6 py-4">Status</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {principals.length === 0 ? (
                <tr>
                    <td colSpan={4} className="px-6 py-8 text-center text-slate-400">
                        No principals created yet. Click "Add Principal" to start.
                    </td>
                </tr>
              ) : (
                principals.map(p => (
                    <tr key={p.uid} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 py-4 font-medium text-slate-900 flex items-center gap-3">
                        <img src={p.avatarUrl} className="w-8 h-8 rounded-full" />
                        {p.name}
                    </td>
                    <td className="px-6 py-4 font-mono text-slate-600">{p.schoolID}</td>
                    <td className="px-6 py-4">
                        <span className="px-2 py-1 bg-green-100 text-green-700 rounded-full text-xs">Active</span>
                    </td>
                    <td className="px-6 py-4 text-right">
                        <div className="flex items-center justify-end gap-2">
                          <button 
                              onClick={() => openEditModal(p)}
                              className="p-2 text-blue-500 hover:bg-blue-50 rounded-lg transition-colors"
                              title="Edit Principal"
                          >
                              <Pencil size={18} />
                          </button>
                          <button 
                              onClick={() => handleRemovePrincipal(p.uid, p.name)}
                              className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                              title="Remove Principal"
                          >
                              <Trash2 size={18} />
                          </button>
                        </div>
                    </td>
                    </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* Add/Edit Principal Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-xl p-8 w-full max-w-md">
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-xl font-bold flex items-center gap-2">
                    <UserPlus className="text-blue-600" />
                    {editingId ? 'Edit Principal' : 'New Principal'}
                </h2>
                <button onClick={() => setShowAddModal(false)} className="text-slate-400 hover:text-slate-600">✕</button>
            </div>

            <form onSubmit={handleSavePrincipal} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Full Name</label>
                <input 
                  type="text" 
                  required
                  value={newPrincipalName}
