interface SidebarProps {
  user: User;
  onLogout: () => void;
  currentPage: string;
  onNavigate: (page: string) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ user, onLogout, currentPage, onNavigate }) => {

  const getMenuItems = () => {
    const common = [
      { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
      { id: 'profile', label: 'My Profile', icon: Users },
    ];

    if (user.role === UserRole.PRINCIPAL) {
      return [
        ...common,
        { id: 'academics', label: 'Academics', icon: BookOpen },
        { id: 'settings', label: 'School Settings', icon: Settings },
      ];
    }

    if (user.role === UserRole.TEACHER) {
      return [
        ...common,
        { id: 'classes', label: 'My Classes', icon: BookOpen },
        { id: 'grades', label: 'Student Grades', icon: GraduationCap },
      ];
    }

    if (user.role === UserRole.STUDENT) {
      return [
        ...common,
        { id: 'grades', label: 'My Grades', icon: GraduationCap },
      ];
    }

    if (user.role === UserRole.SUPREME_ADMIN) {
      return [
        { id: 'dashboard', label: 'System Overview', icon: ShieldAlert },
        { id: 'db-management', label: 'DB Management', icon: Settings },
      ];
    }

    return common;
  };

  const menuItems = getMenuItems();

  return (
    <div className="h-screen w-64 bg-slate-900 text-white flex flex-col fixed left-0 top-0 shadow-xl z-50 transition-all">
      <div className="p-6 border-b border-slate-700">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center font-bold text-xl">
            N
          </div>
          <div>
            <h1 className="font-bold text-lg tracking-tight">NEXUS ERP</h1>
            <p className="text-xs text-slate-400">School Management</p>
          </div>
        </div>
      </div>

      <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
        {menuItems.map((item) => {
          const Icon = item.icon;
          const active = currentPage === item.id;
          return (
            <button
              key={item.id}
              onClick={() => onNavigate(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${
                active 
                  ? 'bg-blue-600 text-white shadow-md' 
                  : 'text-slate-400 hover:bg-slate-800 hover:text-white'
              }`}
            >
              <Icon size={20} />
              <span className="font-medium text-sm">{item.label}</span>
            </button>
          );
        })}
      </nav>

      <div className="p-4 border-t border-slate-700 bg-slate-900">
        <div className="flex items-center gap-3 mb-4 px-2">
          <img 
            src={user.avatarUrl} 
            alt="Profile" 
            className="w-8 h-8 rounded-full bg-slate-700 object-cover"
          />
          <div className="overflow-hidden">
            <p className="text-sm font-medium truncate">{user.name}</p>
            <p className="text-xs text-slate-400 truncate capitalize">{user.role}</p>
          </div>
        </div>
        <button
          onClick={onLogout}
          className="w-full flex items-center gap-2 px-4 py-2 text-red-400 hover:bg-red-900/20 hover:text-red-300 rounded-lg transition-colors text-sm"
        >
          <LogOut size={16} />
          <span>Sign Out</span>
        </button>
      </div>
    </div>
  );
};

