              {students.length === 0 ? (
                  <tr><td colSpan={4} className="px-6 py-8 text-center text-slate-400">No students found. Go to "My Classes" to add them.</td></tr>
              ) : (
                students.map((student) => {
                    const isPresent = student.attendanceToday === true;
                    const isAbsent = student.attendanceToday === false;

                    return (
                    <tr key={student.id} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-6 py-4">
                        <div className="font-medium text-slate-900">{student.name}</div>
                        </td>
                        <td className="px-6 py-4 font-mono text-sm text-slate-500">
                        {student.schoolID}
                        </td>
                        <td className="px-6 py-4 text-center">
                            <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border ${getAttendanceStatusColor(student.attendanceToday)}`}>
                                {isPresent ? 'Present' : isAbsent ? 'Absent' : 'Not Marked'}
                            </span>
                        </td>
                        <td className="px-6 py-4 text-right">
                        <div className="flex items-center justify-end gap-2">
                            <button 
                                onClick={() => handleToggleAttendance(student.id)}
                                className={`p-2 rounded-lg transition-colors ${
                                    isPresent 
                                    ? 'bg-green-100 text-green-700 hover:bg-green-200' 
                                    : 'bg-slate-100 text-slate-400 hover:bg-slate-200'
                                }`}
                            >
                                <CheckSquare size={18} />
                            </button>
                            <button 
                                onClick={() => handleToggleAttendance(student.id)}
                                className={`p-2 rounded-lg transition-colors ${
                                    isAbsent 
                                    ? 'bg-red-100 text-red-700 hover:bg-red-200' 
                                    : 'bg-slate-100 text-slate-400 hover:bg-slate-200'
                                }`}
                            >
                                <Square size={18} className={isAbsent ? "fill-current" : ""} />
                            </button>
                        </div>
                        </td>
                    </tr>
                    );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default TeacherDashboard;

import React from 'react';
import { User, StudentRecord, MarkEntry } from '../types';
import { Book, Award, Clock, GraduationCap, Phone, Mail, User as UserIcon, Hash } from 'lucide-react';
import { getStoredStudents } from '../services/storage';

interface StudentDashboardProps {
  user: User;
  currentPage?: string;
}

const StudentDashboard: React.FC<StudentDashboardProps> = ({ user, currentPage = 'dashboard' }) => {

  const getStudentProfile = (): StudentRecord | undefined => {
    return getStoredStudents().find(s => s.schoolID === user.schoolID);
  };

  const calculateGrade = (score: number) => {
    if (score >= 90) return 'A';
    if (score >= 85) return 'B+';
    if (score >= 80) return 'B';
    if (score >= 75) return 'C+';
    if (score >= 70) return 'C';
    if (score >= 60) return 'D';
    return 'F';
  };

  if (currentPage === 'profile') {
    const studentProfile = getStudentProfile();

    if (!studentProfile) {
        return (
            <div className="p-8 text-center bg-white rounded-xl shadow-sm border border-slate-200">
                <div className="text-slate-400 mb-2">
                    <UserIcon size={48} className="mx-auto opacity-50" />
                </div>
                <h3 className="text-lg font-bold text-slate-700">Profile Not Found</h3>
                <p className="text-slate-500">
                    Detailed information is not available. Please ask your class teacher to update your student record.
                </p>
            </div>
        );
    }

    return (
        <div className="space-y-6">
             <h1 className="text-2xl font-bold text-slate-800">My Profile</h1>
             <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                {/* Header Section */}
                <div className="bg-slate-50 p-8 border-b border-slate-100 flex flex-col md:flex-row items-center gap-6">
                    <img 
                        src={user.avatarUrl} 
                        alt={studentProfile.name} 
                        className="w-24 h-24 rounded-full bg-blue-100 object-cover border-4 border-white shadow-sm"
                    />
                    <div className="text-center md:text-left space-y-1">
                        <h2 className="text-2xl font-bold text-slate-900">{studentProfile.name}</h2>
                        <div className="flex flex-wrap justify-center md:justify-start gap-2 text-slate-500 font-mono text-sm">
                            <span className="px-3 py-1 bg-white border border-slate-200 rounded-full text-slate-700 flex items-center gap-1">
                                <Hash size={14} /> {studentProfile.schoolID}
                            </span>
                        </div>
                    </div>
                </div>

                {/* Details Grid */}
                <div className="p-8 grid grid-cols-1 md:grid-cols-2 gap-10">

                    {/* Academic Info */}
                    <div className="space-y-6">
                        <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest border-b border-blue-100 pb-2">Academic Information</h3>
                        <div className="grid grid-cols-2 gap-6">
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Class</label>
                                <p className="text-lg font-medium text-slate-800">{studentProfile.className}</p>
                            </div>
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Roll Number</label>
                                <p className="text-lg font-medium text-slate-800">{studentProfile.rollNumber}</p>
                            </div>
                        </div>
                    </div>

                    {/* Personal Info */}
                    <div className="space-y-6">
                        <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest border-b border-blue-100 pb-2">Personal Details</h3>
                        <div className="grid grid-cols-1 gap-4">
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">Age</label>
                                <p className="text-lg font-medium text-slate-800">
                                    {studentProfile.age ? `${studentProfile.age} Years Old` : <span className="text-slate-400 italic">Not set</span>}
                                </p>
                            </div>
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">School Email</label>
                                <div className="flex items-center gap-2 text-slate-800 font-medium text-lg">
                                    <Mail size={18} className="text-slate-400" />
                                    {studentProfile.email || <span className="text-slate-400 italic">Not set</span>}
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Family Contact */}
                    <div className="space-y-6 md:col-span-2">
                        <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest border-b border-blue-100 pb-2">Guardian Contacts</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                             <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-xl border border-slate-100">
                                <div className="p-3 bg-blue-100 text-blue-600 rounded-lg">
                                    <Phone size={20} />
                                </div>
                                <div>
                                    <label className="block text-xs text-slate-500 font-bold uppercase">Father's Contact</label>
                                    <p className="text-slate-900 font-semibold">{studentProfile.fatherContact || 'N/A'}</p>
                                </div>
                             </div>
