  const [marksList, setMarksList] = useState<MarkEntry[]>([]);
  const [newSubject, setNewSubject] = useState('');
  const [newMidTerm, setNewMidTerm] = useState('');
  const [newFinal, setNewFinal] = useState('');

  useEffect(() => {
    setStudents(getStoredStudents());
    setUsers(getStoredUsers());
  }, []);

  const handleToggleAttendance = (id: string) => {
    setStudents(prev => prev.map(s => {
      if (s.id === id) {
        return { ...s, attendanceToday: s.attendanceToday === false ? true : false }; 
      }
      return s;
    }));
    setHasChanges(true);
  };

  const markAllPresent = () => {
    setStudents(prev => prev.map(s => ({ ...s, attendanceToday: true })));
    setHasChanges(true);
  };

  const saveAttendance = () => {
    students.forEach(s => updateStudent(s));
    setHasChanges(false);
    alert("Attendance saved to database!");
  };

  // --- STUDENT MODAL LOGIC ---

  const openAddModal = () => {
    setEditingId(null);
    setName('');
    setAge('');
    setGender('Male');
    setSchoolID('');
    setPassword('');
    setRollNo((students.length + 1).toString());
    setClassName(currentUser.assignedClass || '10-A');
    setEmail('');
    setFatherContact('');
    setMotherContact('');
    setShowModal(true);
  };

  const openEditModal = (student: StudentRecord) => {
    setEditingId(student.id);
    const userLogin = users.find(u => u.schoolID === student.schoolID);

    setName(student.name);
    setAge(student.age?.toString() || '');
    setGender(student.gender || 'Male');
    setSchoolID(student.schoolID);
    setPassword(userLogin?.password || '');
    setRollNo(student.rollNumber.toString());
    setClassName(student.className);
    setEmail(student.email || '');
    setFatherContact(student.fatherContact || '');
    setMotherContact(student.motherContact || '');
    setShowModal(true);
  };

  const handleSaveStudent = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId) {
      // Update existing
      const existingStudent = students.find(s => s.id === editingId);
      if (!existingStudent) return;

      const updatedRecord: StudentRecord = {
        ...existingStudent,
        name,
        schoolID,
        rollNumber: parseInt(rollNo),
        className,
        age: parseInt(age),
        gender,
        email,
        fatherContact,
        motherContact
      };

      const associatedUser = users.find(u => u.schoolID === existingStudent.schoolID);
      if (associatedUser) {
        const updatedUser: User = {
          ...associatedUser,
          name,
          schoolID,
          password,
          className,
          gender,
          email: email
        };
        updateUser(updatedUser);
      }

      updateStudent(updatedRecord);
      alert(`Student ${name} updated successfully.`);

    } else {
      // Create new
      const newRecord: StudentRecord = {
        id: generateId('s'),
        name,
        schoolID,
        rollNumber: parseInt(rollNo) || 0,
        attendanceToday: null,
        gradeAverage: 0,
        className,
        age: parseInt(age),
        gender,
        email,
        fatherContact,
        motherContact,
        marks: []
      };

      const newUser: User = {
        uid: generateId('u'),
        name,
        schoolID,
        role: UserRole.STUDENT,
        className,
        password,
        gender,
        avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(name)}&background=f59e0b&color=fff`
      };

      addStudent(newRecord);
      addUser(newUser);
      alert(`Student Added! Login ID: ${schoolID}, Password: ${password}`);
    }

    setStudents(getStoredStudents());
    setUsers(getStoredUsers());
    setShowModal(false);
  };

  // --- MARKS LOGIC ---

  const openMarksModal = (student: StudentRecord) => {
    setCurrentMarksStudent(student);
    setMarksList(student.marks || []);
    setNewSubject('');
    setNewMidTerm('');
    setNewFinal('');
    setShowMarksModal(true);
  };

  const handleAddMark = () => {
    if (!newSubject || !newMidTerm || !newFinal) {
        alert("Please fill all fields.");
        return;
    }
    const newEntry: MarkEntry = {
        subject: newSubject,
        midTerm: parseFloat(newMidTerm),
        final: parseFloat(newFinal)
    };
    setMarksList([...marksList, newEntry]);
    setNewSubject('');
    setNewMidTerm('');
    setNewFinal('');
  };

  const handleRemoveMark = (index: number) => {
    const updated = [...marksList];
    updated.splice(index, 1);
    setMarksList(updated);
  };

  const saveMarks = () => {
    if (!currentMarksStudent) return;

    // Calculate new average
    let totalScore = 0;
    let count = 0;
    marksList.forEach(m => {
        totalScore += (m.midTerm + m.final) / 2;
        count++;
    });
    const newAverage = count > 0 ? parseFloat((totalScore / count).toFixed(1)) : 0;

    const updatedStudent: StudentRecord = {
        ...currentMarksStudent,
        marks: marksList,
        gradeAverage: newAverage
    };

    updateStudent(updatedStudent);
    setStudents(getStoredStudents()); // Refresh list
    setShowMarksModal(false);
    alert(`Marks updated for ${currentMarksStudent.name}`);
  };

  const getAttendanceStatusColor = (status: boolean | null) => {
    if (status === true) return 'bg-green-100 text-green-700 border-green-200';
    if (status === false) return 'bg-red-100 text-red-700 border-red-200';
    return 'bg-slate-100 text-slate-500 border-slate-200';
  };

  // --- RENDERING ---

  if (currentPage === 'grades') {
      return (
          <div className="space-y-6">
              <header className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-slate-800">Student Grades</h1>
                    <p className="text-slate-500">Manage Assessments & Results</p>
                </div>
              </header>

              <div className="bg-white rounded-xl shadow-sm border border-slate-100">
                <table className="w-full text-left">
                    <thead className="bg-slate-50 text-slate-500 text-xs uppercase">
                        <tr>
                            <th className="px-6 py-4">Student Name</th>
                            <th className="px-6 py-4">Roll No</th>
                            <th className="px-6 py-4">Overall GPA</th>
                            <th className="px-6 py-4 text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {students.length === 0 ? (
                             <tr><td colSpan={4} className="px-6 py-8 text-center text-slate-400">No students found.</td></tr>
                        ) : (
                            students.map(s => (
                                <tr key={s.id} className="hover:bg-slate-50/50">
                                    <td className="px-6 py-4 font-medium">{s.name}</td>
                                    <td className="px-6 py-4 text-slate-600">{s.rollNumber}</td>
                                    <td className="px-6 py-4 font-bold text-blue-600">
                                        {s.gradeAverage > 0 ? `${s.gradeAverage}%` : 'N/A'}
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <button 
                                            onClick={() => openMarksModal(s)}
                                            className="px-3 py-1.5 bg-blue-50 text-blue-600 rounded-lg text-sm font-medium hover:bg-blue-100 transition-colors flex items-center gap-2 ml-auto"
                                        >
                                            <GraduationCap size={16} /> Manage Marks
                                        </button>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
              </div>

              {/* Marks Modal */}
              {showMarksModal && currentMarksStudent && (
                  <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10">
                    <div className="bg-white rounded-xl p-8 w-full max-w-3xl shadow-2xl">
                        <div className="flex justify-between items-center mb-6 border-b border-slate-100 pb-4">
                            <div>
                                <h2 className="text-xl font-bold text-slate-800">Manage Marks</h2>
                                <p className="text-slate-500 text-sm">Student: {currentMarksStudent.name} (Roll: {currentMarksStudent.rollNumber})</p>
                            </div>
                            <button onClick={() => setShowMarksModal(false)} className="text-slate-400 hover:text-slate-600 text-2xl">&times;</button>
                        </div>

                        <div className="space-y-6">
                            {/* Input Row */}
                            <div className="flex gap-3 items-end bg-slate-50 p-4 rounded-lg border border-slate-200">
                                <div className="flex-1">
                                    <label className="block text-xs font-bold text-slate-500 mb-1">Subject</label>
                                    <input 
                                        className="w-full px-3 py-2 border rounded-md text-sm"
                                        placeholder="e.g. Mathematics"
                                        value={newSubject}
                                        onChange={e => setNewSubject(e.target.value)}
                                    />
                                </div>
                                <div className="w-24">
                                    <label className="block text-xs font-bold text-slate-500 mb-1">Mid-Term</label>
                                    <input 
                                        type="number"
                                        className="w-full px-3 py-2 border rounded-md text-sm"
                                        placeholder="0-100"
                                        value={newMidTerm}
                                        onChange={e => setNewMidTerm(e.target.value)}
                                    />
                                </div>
                                <div className="w-24">
                                    <label className="block text-xs font-bold text-slate-500 mb-1">Finals</label>
                                    <input 
                                        type="number"
                                        className="w-full px-3 py-2 border rounded-md text-sm"
                                        placeholder="0-100"
                                        value={newFinal}
                                        onChange={e => setNewFinal(e.target.value)}
                                    />
                                </div>
                                <button 
                                    onClick={handleAddMark}
                                    className="px-4 py-2 bg-blue-600 text-white rounded-md text-sm font-medium hover:bg-blue-700 flex items-center gap-1 h-[38px]"
                                >
                                    <Plus size={16} /> Add
                                </button>
                            </div>

                            {/* List */}
                            <table className="w-full text-left border border-slate-200 rounded-lg overflow-hidden">
                                <thead className="bg-slate-100 text-slate-600 text-xs uppercase">
                                    <tr>
                                        <th className="px-4 py-3">Subject</th>
                                        <th className="px-4 py-3">Mid-Term</th>
                                        <th className="px-4 py-3">Finals</th>
                                        <th className="px-4 py-3">Average</th>
                                        <th className="px-4 py-3 text-right">Action</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100">
                                    {marksList.length === 0 ? (
                                        <tr><td colSpan={5} className="p-6 text-center text-slate-400 text-sm">No marks added yet.</td></tr>
                                    ) : (
                                        marksList.map((m, idx) => (
                                            <tr key={idx}>
                                                <td className="px-4 py-3 font-medium">{m.subject}</td>
                                                <td className="px-4 py-3 text-slate-600">{m.midTerm}</td>
                                                <td className="px-4 py-3 text-slate-600">{m.final}</td>
                                                <td className="px-4 py-3 font-bold text-blue-600">{((m.midTerm + m.final) / 2).toFixed(1)}</td>
                                                <td className="px-4 py-3 text-right">
                                                    <button onClick={() => handleRemoveMark(idx)} className="text-red-500 hover:text-red-700">
                                                        <Trash2 size={16} />
                                                    </button>
                                                </td>
                                            </tr>
                                        ))
                                    )}
                                </tbody>
                            </table>
                        </div>

                        <div className="mt-8 flex justify-end gap-3 pt-4 border-t border-slate-100">
                            <button onClick={() => setShowMarksModal(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-50 rounded-lg">Cancel</button>
                            <button onClick={saveMarks} className="px-6 py-2 bg-green-600 text-white font-medium rounded-lg hover:bg-green-700">Save Grades</button>
                        </div>
                    </div>
                  </div>
              )}
          </div>
      );
  }

  if (currentPage === 'classes') {
    return (
       <div className="space-y-6">
            <header className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-slate-800">My Classes</h1>
                    <p className="text-slate-500">Manage Student Roster & Information</p>
                </div>
                <button 
                    onClick={openAddModal}
                    className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                >
                    <UserPlus size={18} /> Add Student
                </button>
            </header>

            <div className="bg-white rounded-xl shadow-sm border border-slate-100">
                <table className="w-full text-left">
                    <thead className="bg-slate-50 text-slate-500 text-xs uppercase">
                        <tr>
                            <th className="px-6 py-4">Name</th>
                            <th className="px-6 py-4">Roll No</th>
                            <th className="px-6 py-4">ID</th>
                            <th className="px-6 py-4">Class</th>
                            <th className="px-6 py-4">Parents Contact</th>
                            <th className="px-6 py-4">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {students.length === 0 ? (
                             <tr><td colSpan={6} className="px-6 py-8 text-center text-slate-400">No students yet. Click "Add Student".</td></tr>
                        ) : (
                            students.map(s => (
                                <tr key={s.id} className="hover:bg-slate-50/50">
                                    <td className="px-6 py-4 font-medium">{s.name}</td>
                                    <td className="px-6 py-4 text-slate-600">{s.rollNumber}</td>
                                    <td className="px-6 py-4 font-mono text-sm text-slate-600">{s.schoolID}</td>
                                    <td className="px-6 py-4">{s.className}</td>
                                    <td className="px-6 py-4 text-sm text-slate-500">
                                      {s.fatherContact ? `F: ${s.fatherContact}` : ''}
                                      {s.fatherContact && s.motherContact ? <br/> : ''}
                                      {s.motherContact ? `M: ${s.motherContact}` : ''}
                                    </td>
                                    <td className="px-6 py-4">
                                      <button 
                                        onClick={() => openEditModal(s)}
                                        className="flex items-center gap-1 text-blue-600 hover:text-blue-800 font-medium text-sm"
                                      >
                                        <Pencil size={14} /> Edit
                                      </button>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

             {/* Add/Edit Student Modal */}
            {showModal && (
            <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10">
                <div className="bg-white rounded-xl p-8 w-full max-w-2xl shadow-2xl">
                <div className="flex justify-between items-center mb-6 border-b border-slate-100 pb-4">
                  <h2 className="text-xl font-bold text-slate-800">
                    {editingId ? 'Edit Student Details' : 'Register New Student'}
                  </h2>
                  <button onClick={() => setShowModal(false)} className="text-slate-400 hover:text-slate-600 text-2xl">&times;</button>
                </div>

                <form onSubmit={handleSaveStudent} className="space-y-6">

                    {/* Basic Info Section */}
                    <div>
                      <h3 className="text-xs uppercase font-bold text-slate-400 mb-3 tracking-wider">Student Information</h3>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm mb-1 text-slate-600 font-medium">Full Name</label>
                            <input 
                                className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                                value={name}
                                onChange={e => setName(e.target.value)}
                                placeholder="e.g. Alice Smith"
                                required 
                            />
                        </div>
                        <div>
                            <label className="block text-sm mb-1 text-slate-600 font-medium">Gender</label>
                            <select
                                className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                                value={gender}
                                onChange={e => setGender(e.target.value)}
                            >
                                <option value="Male">Male</option>
                                <option value="Female">Female</option>
                                <option value="Other">Other</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm mb-1 text-slate-600 font-medium">Age</label>
                            <input 
                                type="number"
                                className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                                value={age}
                                onChange={e => setAge(e.target.value)}
                                placeholder="e.g. 15"
                            />
                        </div>
                        <div>
                            <label className="block text-sm mb-1 text-slate-600 font-medium">Roll Number</label>
                            <input 
                                type="number"
                                className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                                value={rollNo}
                                onChange={e => setRollNo(e.target.value)}
                                required 
                            />
                        </div>
                        <div>
                            <label className="block text-sm mb-1 text-slate-600 font-medium">Class (One-line Input)</label>
                            <input 
                                type="text"
                                className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
                                value={className}
                                onChange={e => setClassName(e.target.value)}
                                placeholder="e.g. 10-A"
                                required 
                            />
                        </div>
                        <div>
                            <label className="block text-sm mb-1 text-slate-600 font-medium">School Email</label>
                            <input 
                                type="email"
                                className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                                value={email}
                                onChange={e => setEmail(e.target.value)}
                                placeholder="alice@school.edu"
                            />
                        </div>
                      </div>
                    </div>

                    {/* Login Credentials */}
                    <div>
                      <h3 className="text-xs uppercase font-bold text-slate-400 mb-3 tracking-wider mt-2">Login Credentials</h3>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                         <div>
                            <label className="block text-sm mb-1 text-slate-600 font-medium">School ID (Login)</label>
                            <input 
                                className="w-full px-4 py-2 border border-slate-200 rounded-lg font-mono focus:ring-2 focus:ring-blue-500 outline-none" 
                                value={schoolID}
                                onChange={e => setSchoolID(e.target.value)}
                                placeholder="STD-2024-XXX"
                                required 
                            />
                        </div>
                        <div>
                            <label className="block text-sm mb-1 text-slate-600 font-medium">Password</label>
                            <input 
                                type="text"
                                className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                                value={password}
                                onChange={e => setPassword(e.target.value)}
                                placeholder="Set login password"
                                required 
                            />
                        </div>
                      </div>
                    </div>

                    {/* Family Info */}
                    <div>
                      <h3 className="text-xs uppercase font-bold text-slate-400 mb-3 tracking-wider mt-2">Family & Contact</h3>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm mb-1 text-slate-600 font-medium">Father's Contact No.</label>
                            <input 
                                className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                                value={fatherContact}
                                onChange={e => setFatherContact(e.target.value)}
                                placeholder="+1 234..."
                            />
                        </div>
                        <div>
                            <label className="block text-sm mb-1 text-slate-600 font-medium">Mother's Contact No.</label>
                            <input 
                                className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none" 
                                value={motherContact}
                                onChange={e => setMotherContact(e.target.value)}
                                placeholder="+1 234..."
                            />
                        </div>
                      </div>
                    </div>

                    <div className="flex gap-3 mt-6 pt-4 border-t border-slate-100">
                        <button 
                            type="button" 
                            onClick={() => setShowModal(false)} 
                            className="flex-1 py-3 border border-slate-200 text-slate-600 rounded-lg hover:bg-slate-50 font-medium"
                        >
                            Cancel
                        </button>
                        <button 
                            type="submit" 
                            className="flex-1 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-medium shadow-sm"
                        >
                            {editingId ? 'Update Student Record' : 'Register Student'}
                        </button>
                    </div>
                </form>
                </div>
            </div>
            )}
       </div>
    );
  }

  // DEFAULT DASHBOARD
  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Class 10-A</h1>
          <p className="text-slate-500">Daily Attendance & Roster</p>
        </div>

        <div className="flex items-center gap-3">
           <button 
            onClick={markAllPresent}
            className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 text-slate-700 font-medium rounded-lg hover:bg-slate-50 transition-colors shadow-sm"
          >
            <CheckSquare size={18} />
            Mark All Present
          </button>

          <button 
            onClick={saveAttendance}
            disabled={!hasChanges}
            className={`flex items-center gap-2 px-6 py-2 font-medium rounded-lg transition-all shadow-sm ${
              hasChanges 
              ? 'bg-blue-600 text-white hover:bg-blue-700' 
              : 'bg-slate-200 text-slate-400 cursor-not-allowed'
            }`}
          >
            <Save size={18} />
            Save Records
          </button>
        </div>
      </header>

      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        {/* List */}
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-slate-500 text-xs uppercase font-semibold">
              <tr>
                <th className="px-6 py-4">Student Name</th>
                <th className="px-6 py-4">School ID</th>
                <th className="px-6 py-4 text-center">Status</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {students.length === 0 ? (
                  <tr><td colSpan={4} className="px-6 py-8 text-center text-slate-400">No students found. Go to "My Classes" to add them.</td></tr>
              ) : (
                students.map((student) => {
                    const isPresent = student.attendanceToday === true;
                    const isAbsent = student.attendanceToday === false;

                    return (
                    <tr key={student.id} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-6 py-4">
                        <div className="font-medium text-slate-900">{student.name}</div>
                        </td>
                        <td className="px-6 py-4 font-mono text-sm text-slate-500">
                        {student.schoolID}
                        </td>
                        <td className="px-6 py-4 text-center">
                            <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border ${getAttendanceStatusColor(student.attendanceToday)}`}>
                                {isPresent ? 'Present' : isAbsent ? 'Absent' : 'Not Marked'}
                            </span>
                        </td>
                        <td className="px-6 py-4 text-right">
                        <div className="flex items-center justify-end gap-2">
                            <button 
                                onClick={() => handleToggleAttendance(student.id)}
                                className={`p-2 rounded-lg transition-colors ${
                                    isPresent 
                                    ? 'bg-green-100 text-green-700 hover:bg-green-200' 
                                    : 'bg-slate-100 text-slate-400 hover:bg-slate-200'
                                }`}
                            >
                                <CheckSquare size={18} />
                            </button>
                            <button 
                                onClick={() => handleToggleAttendance(student.id)}
                                className={`p-2 rounded-lg transition-colors ${
                                    isAbsent 
                                    ? 'bg-red-100 text-red-700 hover:bg-red-200' 
                                    : 'bg-slate-100 text-slate-400 hover:bg-slate-200'
                                }`}
                            >
                                <Square size={18} className={isAbsent ? "fill-current" : ""} />
                            </button>
                        </div>
                        </td>
                    </tr>
                    );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

