                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Assign Class</label>
                        <input 
                            className="w-full px-4 py-2 border rounded-lg" 
                            placeholder="e.g. 10-A"
