                                    {studentProfile.gender || 'Not set'}
                                </p>
                            </div>
                            <div>
                                <label className="block text-xs text-slate-400 font-medium uppercase mb-1">School Email</label>
                                <div className="flex items-center gap-2 text-slate-800 font-medium text-lg">
                                    <Mail size={18} className="text-slate-400" />
                                    {studentProfile.email || <span className="text-slate-400 italic">Not set</span>}
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Family Contact */}
                    <div className="space-y-6 md:col-span-2">
                        <h3 className="text-xs font-bold text-blue-600 uppercase tracking-widest border-b border-blue-100 pb-2">Guardian Contacts</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                             <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-xl border border-slate-100">
                                <div className="p-3 bg-blue-100 text-blue-600 rounded-lg">
                                    <Phone size={20} />
                                </div>
                                <div>
                                    <label className="block text-xs text-slate-500 font-bold uppercase">Father's Contact</label>
                                    <p className="text-slate-900 font-semibold">{studentProfile.fatherContact || 'N/A'}</p>
                                </div>
                             </div>
                             <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-xl border border-slate-100">
                                <div className="p-3 bg-purple-100 text-purple-600 rounded-lg">
                                    <Phone size={20} />
                                </div>
                                <div>
                                    <label className="block text-xs text-slate-500 font-bold uppercase">Mother's Contact</label>
                                    <p className="text-slate-900 font-semibold">{studentProfile.motherContact || 'N/A'}</p>
                                </div>
                             </div>
                        </div>
                    </div>
                </div>
             </div>
        </div>
    );
  }

  if (currentPage === 'announcements') {
      return (
          <div className="space-y-6">
              <header className="mb-6">
                 <h1 className="text-2xl font-bold text-slate-800">News & Events</h1>
                 <p className="text-slate-500">Latest updates from the school administration.</p>
              </header>

              <div className="grid gap-6">
                 {announcements.length === 0 ? (
                     <div className="p-12 text-center bg-white rounded-xl border border-slate-100 text-slate-400">
                         <Megaphone size={48} className="mx-auto mb-4 opacity-20" />
                         <p>No announcements at this time.</p>
                     </div>
                 ) : (
                     announcements.map(ann => (
                         <div key={ann.id} className="bg-white rounded-xl p-6 shadow-sm border border-slate-100 border-l-4 border-l-blue-500">
                             <div className="flex justify-between items-start mb-3">
                                 <div>
                                     <h3 className="font-bold text-lg text-slate-800">{ann.title}</h3>
                                     <span className="text-xs text-slate-400 font-mono">{ann.date} • From {ann.author}</span>
                                 </div>
                             </div>
                             <p className="text-slate-600 leading-relaxed whitespace-pre-wrap">{ann.content}</p>
                         </div>
                     ))
                 )}
              </div>
          </div>
      );
  }

  if (currentPage === 'grades') {
    const studentProfile = getStudentProfile();
    const marks = studentProfile?.marks || [];

    return (
        <div className="space-y-6">
            <h1 className="text-2xl font-bold text-slate-800">Academic Transcript</h1>

            <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                <table className="w-full text-left">
                    <thead className="bg-slate-50 text-slate-500 text-xs uppercase">
                        <tr>
                            <th className="px-6 py-4">Subject</th>
                            <th className="px-6 py-4">Mid-Term</th>
                            <th className="px-6 py-4">Finals</th>
                            <th className="px-6 py-4">Avg Score</th>
                            <th className="px-6 py-4">Grade</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {marks.length === 0 ? (
                            <tr><td colSpan={5} className="p-8 text-center text-slate-400">No grades available yet.</td></tr>
                        ) : (
                            marks.map((m, i) => {
                                const avg = (m.midTerm + m.final) / 2;
                                return (
                                    <tr key={i}>
                                        <td className="px-6 py-4 font-medium">{m.subject}</td>
                                        <td className="px-6 py-4 text-slate-600">{m.midTerm}</td>
                                        <td className="px-6 py-4 text-slate-600">{m.final}</td>
                                        <td className="px-6 py-4 font-bold text-slate-800">{avg.toFixed(1)}</td>
                                        <td className={`px-6 py-4 font-bold ${avg >= 70 ? 'text-green-600' : 'text-red-500'}`}>
                                            {calculateGrade(avg)}
                                        </td>
                                    </tr>
                                );
                            })
                        )}
                    </tbody>
                </table>
            </div>

            {studentProfile && studentProfile.gradeAverage > 0 && (
                <div className="p-4 bg-blue-50 border border-blue-100 rounded-lg text-sm text-blue-700 flex justify-between items-center">
                    <span>Cumulative Grade Average</span>
                    <span className="font-bold text-lg">{studentProfile.gradeAverage}%</span>
                </div>
            )}
        </div>
    )
  }

  return (
    <div className="space-y-6">
      <header className="bg-gradient-to-r from-blue-600 to-indigo-700 rounded-2xl p-8 text-white shadow-lg">
        <div className="flex items-center gap-6">
          <img 
            src={user.avatarUrl} 
            alt="Profile" 
            className="w-20 h-20 rounded-full border-4 border-white/30 bg-slate-700"
          />
          <div>
            <h1 className="text-3xl font-bold mb-1">Hello, {user.name}</h1>
            <p className="text-blue-100 font-mono opacity-80">{user.schoolID} • Class {user.className || 'N/A'}</p>
          </div>
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Recent Grades */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h2 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
            <Award className="text-yellow-500" />
            Recent Grades
          </h2>
          {/* Dynamic Recent Grades */}
          <div className="space-y-4">
            {getStudentProfile()?.marks?.slice(0, 3).map((item, idx) => {
                const score = (item.midTerm + item.final) / 2;
                return (
                    <div key={idx} className="flex items-center justify-between p-3 bg-slate-50 rounded-lg">
                        <div>
                            <p className="font-semibold text-slate-700">{item.subject}</p>
                            <p className="text-xs text-slate-500">Latest Assessment</p>
                        </div>
                        <div className="text-right">
                            <span className="text-lg font-bold text-slate-800">{calculateGrade(score)}</span>
                            <p className="text-xs text-slate-500">{score}%</p>
                        </div>
                    </div>
                );
            })}
             {(!getStudentProfile()?.marks || getStudentProfile()?.marks?.length === 0) && (
                 <p className="text-sm text-slate-400 text-center py-4">No grades recorded yet.</p>
             )}
          </div>
        </div>

        {/* Attendance Summary */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
           <h2 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
            <Clock className="text-blue-500" />
            Attendance Overview
          </h2>
          <div className="flex items-center justify-center py-6">
             <div className="relative h-32 w-32 rounded-full border-8 border-slate-100 flex items-center justify-center">
                <div className="absolute inset-0 border-8 border-blue-600 rounded-full border-t-transparent rotate-[-45deg]" style={{ clipPath: 'polygon(0 0, 100% 0, 100% 100%, 0 100%)' }}></div>
                <div className="text-center">
                    <span className="text-2xl font-bold text-slate-800">100%</span>
                    <p className="text-xs text-slate-400">Present</p>
                </div>
             </div>
          </div>
        </div>

        {/* Assignments */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 md:col-span-2">
          <h2 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
            <Book className="text-purple-500" />
            Active Assignments
          </h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="border border-slate-200 rounded-lg p-4 hover:border-blue-300 transition-colors cursor-pointer group">
                <div className="flex justify-between items-start mb-2">
                    <span className="bg-purple-100 text-purple-700 text-xs px-2 py-1 rounded">History</span>
                    <span className="text-xs text-slate-400">Due Tomorrow</span>
                </div>
                <h3 className="font-semibold text-slate-700 group-hover:text-blue-600">World War II Essay</h3>
                <p className="text-sm text-slate-500 mt-1">Submit PDF via portal.</p>
            </div>
            <div className="border border-slate-200 rounded-lg p-4 hover:border-blue-300 transition-colors cursor-pointer group">
                <div className="flex justify-between items-start mb-2">
                    <span className="bg-green-100 text-green-700 text-xs px-2 py-1 rounded">Science</span>
                    <span className="text-xs text-slate-400">Due Friday</span>
                </div>
                <h3 className="font-semibold text-slate-700 group-hover:text-blue-600">Lab Report: Chemistry</h3>
                <p className="text-sm text-slate-500 mt-1">Complete section 1-4.</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StudentDashboard;

import React, { useState, useEffect } from 'react';
import { StudentRecord, User, UserRole, MarkEntry, Announcement } from '../types';
import { getStoredStudents, addStudent, updateStudent, generateId, getStoredUsers, addUser, updateUser, getStoredAnnouncements } from '../services/storage';
import { CheckSquare, Square, Save, UserPlus, Pencil, GraduationCap, Plus, Trash2, Megaphone, SortAsc } from 'lucide-react';

interface Props {
  currentPage?: string;
  currentUser: User;
}

const TeacherDashboard: React.FC<Props> = ({ currentPage = 'dashboard', currentUser }) => {
  const [students, setStudents] = useState<StudentRecord[]>([]);
  const [hasChanges, setHasChanges] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [users, setUsers] = useState<User[]>([]);
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);

  // Student Form State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [name, setName] = useState('');
  const [age, setAge] = useState('');
  const [gender, setGender] = useState('Male'); // Added Gender
  const [schoolID, setSchoolID] = useState('');
  const [password, setPassword] = useState(''); 
  const [rollNo, setRollNo] = useState('');
  const [className, setClassName] = useState('10-A');
  const [email, setEmail] = useState('');
  const [fatherContact, setFatherContact] = useState('');
  const [motherContact, setMotherContact] = useState('');

  // Marks Form State
  const [showMarksModal, setShowMarksModal] = useState(false);
  const [currentMarksStudent, setCurrentMarksStudent] = useState<StudentRecord | null>(null);
  const [marksList, setMarksList] = useState<MarkEntry[]>([]);
  const [newSubject, setNewSubject] = useState('');
  const [newMidTerm, setNewMidTerm] = useState('');
  const [newFinal, setNewFinal] = useState('');

  useEffect(() => {
    setStudents(getStoredStudents());
    setUsers(getStoredUsers());

    // Fetch and filter announcements
    const allAnn = getStoredAnnouncements();
    const relevantAnn = allAnn.filter(a => a.audience === 'all' || a.audience === 'teacher');
    setAnnouncements(relevantAnn);
  }, []);

  const handleToggleAttendance = (id: string) => {
    setStudents(prev => prev.map(s => {
      if (s.id === id) {
        return { ...s, attendanceToday: s.attendanceToday === false ? true : false }; 
      }
      return s;
    }));
    setHasChanges(true);
  };

  const markAllPresent = () => {
    setStudents(prev => prev.map(s => ({ ...s, attendanceToday: true })));
    setHasChanges(true);
  };

  const saveAttendance = () => {
    students.forEach(s => updateStudent(s));
    setHasChanges(false);
    alert("Attendance saved to database!");
  };

  const handleAutoSortRollNumbers = () => {
    if (students.length === 0) return;

    if (!window.confirm("This will sort all students alphabetically by name and re-assign Roll Numbers (1, 2, 3...) sequentially. Continue?")) {
        return;
    }

    const sorted = [...students].sort((a, b) => a.name.localeCompare(b.name));

    // Update logic
    sorted.forEach((s, i) => {
        const updatedRecord = { ...s, rollNumber: i + 1 };
        updateStudent(updatedRecord);
    });

    setStudents(getStoredStudents());
    alert("Students sorted and Roll Numbers updated.");
  };

  // --- STUDENT MODAL LOGIC ---

  const openAddModal = () => {
    setEditingId(null);
    setName('');
    setAge('');
    setGender('Male');
    setSchoolID('');
    setPassword('');
    setRollNo((students.length + 1).toString());
    setClassName(currentUser.assignedClass || '10-A');
    setEmail('');
    setFatherContact('');
    setMotherContact('');
    setShowModal(true);
  };

  const openEditModal = (student: StudentRecord) => {
    setEditingId(student.id);
    const userLogin = users.find(u => u.schoolID === student.schoolID);

    setName(student.name);
    setAge(student.age?.toString() || '');
    setGender(student.gender || 'Male');
    setSchoolID(student.schoolID);
    setPassword(userLogin?.password || '');
    setRollNo(student.rollNumber.toString());
    setClassName(student.className);
    setEmail(student.email || '');
    setFatherContact(student.fatherContact || '');
    setMotherContact(student.motherContact || '');
    setShowModal(true);
  };

  const handleSaveStudent = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId) {
      // Update existing
      const existingStudent = students.find(s => s.id === editingId);
      if (!existingStudent) return;

      const updatedRecord: StudentRecord = {
        ...existingStudent,
        name,
        schoolID,
        rollNumber: parseInt(rollNo),
        className,
        age: parseInt(age),
        gender,
        email,
        fatherContact,
        motherContact
      };

      const associatedUser = users.find(u => u.schoolID === existingStudent.schoolID);
      if (associatedUser) {
        const updatedUser: User = {
          ...associatedUser,
          name,
          schoolID,
          password,
          className,
          gender,
          email: email
        };
        updateUser(updatedUser);
      }

      updateStudent(updatedRecord);
      alert(`Student ${name} updated successfully.`);

    } else {
      // Create new
      const newRecord: StudentRecord = {
        id: generateId('s'),
        name,
        schoolID,
        rollNumber: parseInt(rollNo) || 0,
        attendanceToday: null,
        gradeAverage: 0,
        className,
        age: parseInt(age),
        gender,
        email,
        fatherContact,
        motherContact,
        marks: []
      };

      const newUser: User = {
        uid: generateId('u'),
        name,
        schoolID,
        role: UserRole.STUDENT,
        className,
        password,
        gender,
        avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(name)}&background=f59e0b&color=fff`
      };

      addStudent(newRecord);
      addUser(newUser);
      alert(`Student Added! Login ID: ${schoolID}, Password: ${password}`);
    }

    setStudents(getStoredStudents());
    setUsers(getStoredUsers());
    setShowModal(false);
  };

  // --- MARKS LOGIC ---

  const openMarksModal = (student: StudentRecord) => {
    setCurrentMarksStudent(student);
    setMarksList(student.marks || []);
    setNewSubject('');
    setNewMidTerm('');
    setNewFinal('');
    setShowMarksModal(true);
  };

  const handleAddMark = () => {
    if (!newSubject || !newMidTerm || !newFinal) {
        alert("Please fill all fields.");
        return;
    }
    const newEntry: MarkEntry = {
        subject: newSubject,
        midTerm: parseFloat(newMidTerm),
        final: parseFloat(newFinal)
    };
    setMarksList([...marksList, newEntry]);
    setNewSubject('');
    setNewMidTerm('');
    setNewFinal('');
  };

  const handleRemoveMark = (index: number) => {
    const updated = [...marksList];
    updated.splice(index, 1);
    setMarksList(updated);
  };

  const saveMarks = () => {
    if (!currentMarksStudent) return;

    // Calculate new average
    let totalScore = 0;
    let count = 0;
    marksList.forEach(m => {
        totalScore += (m.midTerm + m.final) / 2;
        count++;
    });
    const newAverage = count > 0 ? parseFloat((totalScore / count).toFixed(1)) : 0;

    const updatedStudent: StudentRecord = {
        ...currentMarksStudent,
        marks: marksList,
        gradeAverage: newAverage
    };

    updateStudent(updatedStudent);
    setStudents(getStoredStudents()); // Refresh list
    setShowMarksModal(false);
    alert(`Marks updated for ${currentMarksStudent.name}`);
  };

  const getAttendanceStatusColor = (status: boolean | null) => {
    if (status === true) return 'bg-green-100 text-green-700 border-green-200';
    if (status === false) return 'bg-red-100 text-red-700 border-red-200';
    return 'bg-slate-100 text-slate-500 border-slate-200';
  };

  // --- RENDERING ---

  if (currentPage === 'announcements') {
      return (
          <div className="space-y-6">
              <header className="mb-6">
                 <h1 className="text-2xl font-bold text-slate-800">News & Events</h1>
                 <p className="text-slate-500">School-wide announcements and teacher updates.</p>
              </header>

              <div className="grid gap-6">
                 {announcements.length === 0 ? (
                     <div className="p-12 text-center bg-white rounded-xl border border-slate-100 text-slate-400">
                         <Megaphone size={48} className="mx-auto mb-4 opacity-20" />
                         <p>No announcements at this time.</p>
                     </div>
                 ) : (
                     announcements.map(ann => (
                         <div key={ann.id} className="bg-white rounded-xl p-6 shadow-sm border border-slate-100 border-l-4 border-l-blue-500">
                             <div className="flex justify-between items-start mb-3">
                                 <div>
                                     <h3 className="font-bold text-lg text-slate-800">{ann.title}</h3>
                                     <span className="text-xs text-slate-400 font-mono">{ann.date} • From {ann.author}</span>
                                 </div>
                             </div>
                             <p className="text-slate-600 leading-relaxed whitespace-pre-wrap">{ann.content}</p>
                         </div>
                     ))
                 )}
              </div>
          </div>
      );
  }

  if (currentPage === 'grades') {
      return (
          <div className="space-y-6">
              <header className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-slate-800">Student Grades</h1>
                    <p className="text-slate-500">Manage Assessments & Results</p>
                </div>
              </header>

              <div className="bg-white rounded-xl shadow-sm border border-slate-100">
                <table className="w-full text-left">
                    <thead className="bg-slate-50 text-slate-500 text-xs uppercase">
                        <tr>
                            <th className="px-6 py-4">Student Name</th>
                            <th className="px-6 py-4">Roll No</th>
                            <th className="px-6 py-4">Overall GPA</th>
                            <th className="px-6 py-4 text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {students.length === 0 ? (
                             <tr><td colSpan={4} className="px-6 py-8 text-center text-slate-400">No students found.</td></tr>
                        ) : (
                            students.map(s => (
                                <tr key={s.id} className="hover:bg-slate-50/50">
                                    <td className="px-6 py-4 font-medium">{s.name}</td>
                                    <td className="px-6 py-4 text-slate-600">{s.rollNumber}</td>
                                    <td className="px-6 py-4 font-bold text-blue-600">
                                        {s.gradeAverage > 0 ? `${s.gradeAverage}%` : 'N/A'}
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <button 
                                            onClick={() => openMarksModal(s)}
                                            className="px-3 py-1.5 bg-blue-50 text-blue-600 rounded-lg text-sm font-medium hover:bg-blue-100 transition-colors flex items-center gap-2 ml-auto"
                                        >
                                            <GraduationCap size={16} /> Manage Marks
                                        </button>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
              </div>

              {/* Marks Modal */}
              {showMarksModal && currentMarksStudent && (
                  <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 overflow-y-auto py-10">
                    <div className="bg-white rounded-xl p-8 w-full max-w-3xl shadow-2xl">
                        <div className="flex justify-between items-center mb-6 border-b border-slate-100 pb-4">
                            <div>
                                <h2 className="text-xl font-bold text-slate-800">Manage Marks</h2>
                                <p className="text-slate-500 text-sm">Student: {currentMarksStudent.name} (Roll: {currentMarksStudent.rollNumber})</p>
                            </div>
                            <button onClick={() => setShowMarksModal(false)} className="text-slate-400 hover:text-slate-600 text-2xl">&times;</button>
                        </div>

                        <div className="space-y-6">
                            {/* Input Row */}
