import { CloudConfig, ERPDatabase } from '../types';

const DISCOVERY_DOCS = ["https://www.googleapis.com/discovery/v1/apis/drive/v3/rest"];
const SCOPES = "https://www.googleapis.com/auth/drive.file";

let tokenClient: any = null;
let accessToken: string | null = null;

export const initGoogleDrive = async (config: CloudConfig) => {
  if (!config.clientId || !config.enabled) return;

  return new Promise<void>((resolve) => {
    gapi.load('client', async () => {
      await gapi.client.init({
        clientId: config.clientId,
        discoveryDocs: DISCOVERY_DOCS,
      });

      tokenClient = google.accounts.oauth2.initTokenClient({
        client_id: config.clientId,
        scope: SCOPES,
        callback: (response: any) => {
          if (response.error !== undefined) {
            throw (response);
          }
          accessToken = response.access_token;
          resolve();
        },
      });
      resolve();
    });
  });
};

export const signInGoogle = async () => {
  return new Promise<void>((resolve, reject) => {
    if (!tokenClient) {
        reject(new Error("Google Drive client not initialized. Check your Client ID."));
        return;
    }
    tokenClient.callback = (response: any) => {
      if (response.error !== undefined) {
        reject(response);
      }
      accessToken = response.access_token;
      resolve();
    };

    if (accessToken === null) {
      tokenClient.requestAccessToken({ prompt: 'consent' });
    } else {
      tokenClient.requestAccessToken({ prompt: '' });
    }
  });
};

const findOrCreateFile = async (fileName: string) => {
  const response = await gapi.client.drive.files.list({
    q: `name = '${fileName}' and trashed = false`,
    fields: 'files(id, name)',
    spaces: 'drive',
  });

  const files = response.result.files;
  if (files && files.length > 0) {
    return files[0].id;
  }
  return null;
};

export const syncToGoogleDrive = async (data: ERPDatabase) => {
  try {
    if (!accessToken) await signInGoogle();

    const fileName = 'nexus_erp_db.json';
    const fileId = await findOrCreateFile(fileName);
    const content = JSON.stringify(data, null, 2);

    if (fileId) {
      // Update existing file
      await fetch(`https://www.googleapis.com/upload/drive/v3/files/${fileId}?uploadType=media`, {
        method: 'PATCH',
        headers: {
          Authorization: `Bearer ${accessToken}`,
          'Content-Type': 'application/json',
        },
        body: content,
      });
    } else {
      // Create new file
      const metadata = {
        name: fileName,
        mimeType: 'application/json',
      };

      const form = new FormData();
      form.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
      form.append('file', new Blob([content], { type: 'application/json' }));

      await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart', {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${accessToken}`,
        },
        body: form,
      });
    }
    return true;
  } catch (error) {
    console.error('Google Drive Sync Error:', error);
    return false;
  }
};

export const fetchFromGoogleDrive = async (): Promise<ERPDatabase | null> => {
  try {
    if (!accessToken) await signInGoogle();

    const fileName = 'nexus_erp_db.json';
    const fileId = await findOrCreateFile(fileName);

    if (!fileId) return null;

    const response = await fetch(`https://www.googleapis.com/drive/v3/files/${fileId}?alt=media`, {
      headers: {
        Authorization: `Bearer ${accessToken}`,
      },
    });

    return await response.json();
  } catch (error) {
    console.error('Google Drive Fetch Error:', error);
    return null;
  }
};

import React, { useState, useEffect } from 'react';
import { User, UserRole, CloudConfig } from '../types';
import { getStoredUsers, addUser, updateUser, removeUser, generateId, getCloudConfig, saveCloudConfig, getFullDatabase, restoreFullDatabase } from '../services/storage';
import { Shield, Plus, UserPlus, School, Search, Trash2, Pencil, Cloud, CloudUpload, CloudDownload, Settings, Mail, Key, CheckCircle, XCircle, Loader2 } from 'lucide-react';
import { initGoogleDrive, signInGoogle, syncToGoogleDrive, fetchFromGoogleDrive } from '../services/googleDrive';

const AdminDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'overview' | 'principals' | 'cloud'>('overview');
  const [users, setUsers] = useState<User[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);

  // Cloud State
  const [cloudConfig, setCloudConfig] = useState<CloudConfig>(getCloudConfig());
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncMessage, setSyncMessage] = useState<{ text: string, type: 'success' | 'error' | 'info' } | null>(null);

  // Form State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [newPrincipalName, setNewPrincipalName] = useState('');
  const [newPrincipalID, setNewPrincipalID] = useState('');
  const [newPrincipalPassword, setNewPrincipalPassword] = useState('');

  useEffect(() => {
    setUsers(getStoredUsers());
    if (cloudConfig.enabled) {
      initGoogleDrive(cloudConfig);
    }
  }, []);

  const openAddModal = () => {
    setEditingId(null);
    setNewPrincipalName('');
    setNewPrincipalID('');
    setNewPrincipalPassword('');
    setShowAddModal(true);
  };

  const openEditModal = (user: User) => {
    setEditingId(user.uid);
    setNewPrincipalName(user.name);
    setNewPrincipalID(user.schoolID);
    setNewPrincipalPassword(user.password || '');
    setShowAddModal(true);
  };

  const handleSavePrincipal = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      const updatedUser: User = {
        ...users.find(u => u.uid === editingId)!,
        name: newPrincipalName,
        schoolID: newPrincipalID,
        password: newPrincipalPassword,
        avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(newPrincipalName)}&background=3b82f6&color=fff`
      };
      updateUser(updatedUser);
      alert(`Principal ${updatedUser.name} updated!`);
    } else {
      const newUser: User = {
        uid: generateId('u'),
        name: newPrincipalName,
        schoolID: newPrincipalID,
        role: UserRole.PRINCIPAL,
        avatarUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(newPrincipalName)}&background=3b82f6&color=fff`,
        password: newPrincipalPassword
      };
      addUser(newUser);
      alert(`Principal ${newUser.name} added!`);
    }
    setUsers(getStoredUsers());
    setShowAddModal(false);
  };

  const handleRemovePrincipal = (uid: string, name: string) => {
    if (window.confirm(`Are you sure you want to remove Principal "${name}"?`)) {
      removeUser(uid);
      setUsers(getStoredUsers());
    }
  };

  const handleSaveCloudConfig = (e: React.FormEvent) => {
    e.preventDefault();
    saveCloudConfig(cloudConfig);
    initGoogleDrive(cloudConfig);
    setSyncMessage({ text: 'Cloud configuration saved!', type: 'success' });
    setTimeout(() => setSyncMessage(null), 3000);
  };

  const handleCloudSync = async (direction: 'upload' | 'download') => {
    setIsSyncing(true);
    setSyncMessage(null);
    try {
      if (direction === 'upload') {
        const db = getFullDatabase();
        const success = await syncToGoogleDrive(db);
        if (success) {
          const updatedConfig = { ...cloudConfig, lastSync: new Date().toLocaleString() };
          setCloudConfig(updatedConfig);
          saveCloudConfig(updatedConfig);
          setSyncMessage({ text: 'Database successfully synced to Google Drive.', type: 'success' });
        } else {
          setSyncMessage({ text: 'Sync failed. Please check your Client ID and connection.', type: 'error' });
        }
      } else {
        const data = await fetchFromGoogleDrive();
        if (data) {
          if (window.confirm('This will overwrite all local data with the cloud version. Proceed?')) {
            restoreFullDatabase(data);
            setUsers(getStoredUsers());
            setSyncMessage({ text: 'Local database restored from Google Drive.', type: 'success' });
          }
        } else {
          setSyncMessage({ text: 'No cloud database found or access denied.', type: 'error' });
        }
      }
    } catch (err: any) {
      setSyncMessage({ text: err.message || 'Operation failed', type: 'error' });
    } finally {
      setIsSyncing(false);
    }
  };

  const principals = users.filter(u => u.role === UserRole.PRINCIPAL);

  return (
    <div className="space-y-6">
